mapper.select:
select case when a.target_user_id !=0 and a.target_user_id is not null then a.event_id || '_others_' || a.state else a.event_id || '_my' end numKey,count(1) as num from( select eventRes.*, case when eventRes.user_id!=#{userId} then mm.read_state else null end state from gc_user_event_resource eventRes LEFT JOIN gc_master_message mm on mm.res_id = eventRes.id
LEFT JOIN gc_event gcEvent ON eventRes.event_id = gcEvent.id LEFT JOIN gc_video gcVideo ON gcVideo.id = gcEvent.video_id LEFT JOIN gc_subject sub on sub.id=gcVideo.sub_id
where sub.id = #{subId} and (eventRes.target_user_id=#{userId} or eventRes.user_id=#{userId}) group by eventRes.id, mm.read_state
) a group by COALESCE(a.state, 1), a.target_user_id, a.event_id, a.state;

select
	case when  a.target_user_id !=0 and a.target_user_id is not null then a.event_id || '_my'
		 else a.event_id || '_others_' || a.state end numKey,count(1) as num
from(
		select  eventRes.*
			 ,gcEvent.event_title
			 , mm.read_state,
			case when eventRes.user_id!=#{teacherId} and mm.read_state is null then 1 else mm.read_state end state
		from gc_user_event_resource eventRes
				 LEFT JOIN gc_master_message mm on mm.res_id = eventRes.id AND (mm.target_user_id = eventRes.target_user_id or eventRes.target_user_id is null) and mm.target_user_id=#{teacherId}
				 LEFT JOIN gc_event gcEvent ON eventRes.event_id = gcEvent.id
				 LEFT JOIN gc_video gcVideo ON gcVideo.id = gcEvent.video_id
				 LEFT JOIN gc_subject sub on sub.id=gcVideo.sub_id
		where sub.id = #{subId}
		  and (
				(eventRes.user_id=#{teacherId} and eventRes.target_user_id=#{studentId}) or
				(eventRes.user_id=#{studentId})
			)
		group by eventRes.id, gcEvent.event_title, mm.read_state
	) a group by COALESCE(a.state, 1), a.target_user_id, a.event_id, a.state;

SELECT


,concat('[',string_agg(tags.tag_text, ','),']') as course_tags
FROM gc_subject s
left join sys_file f on s.sub_img_id=f.id
left join gc_subject_tags tags on tags.subject_id = s.id and ((tags.master_id = #{masterId}) or (tags.master_id != #{masterId} and tags.type = 1))
WHERE s.master_id = #{masterId}

	AND s.level = #{level}


	AND s.state = #{state}

GROUP BY s.id, f.id
ORDER BY s.order ASC,s.create_time desc,s.id

SELECT

,count(v.id) as videosTotalNum

FROM gc_subject s
left join sys_file f on s.sub_img_id=f.id
left join gc_subject sub1 on sub1.fid = s.id
left join gc_video v on v.sub_id = sub1.id
WHERE s.level = #{level} and s.state = #{state}

	AND s.id not in

		#{channelId}



	and s.create_user = #{createUser}

and s.master_id = #{masterId}
GROUP BY s.id
ORDER BY s.order ASC,s.create_time desc,s.id

select
from gc_subject s left join sys_file f on s.sub_img_id=f.id WHERE s.id in
#{ids}
or s.fid in
#{ids}
order by 'order' asc

SELECT
,concat('[',array_to_string(array_agg(tags.tag_text), ',') ,']') as course_tags FROM gc_subject s left join gc_subject_association subjectAssociation on s.id=subjectAssociation.subject_id or s.fid=subjectAssociation.subject_id left join sys_file f on s.sub_img_id=f.id left join gc_subject_tags tags on tags.subject_id = s.id and ((tags.master_id = #{masterId}) or (tags.master_id != #{masterId} and tags.type = 1)) where subjectAssociation.master_id=#{masterId}
and subjectAssociation.subject_id in
#{subId}
and s.level=0
GROUP BY s.id, subjectAssociation.id, f.id

select count(1) from gc_subject
where


		name=#{name}


		name_index=#{nameIndex}


and master_id = #{masterId} and


		fid is null


		fid = #{fid}



	and id !=#{id}

SELECT

from gc_subject s left join gc_subject s0 on s0.id = s.fid
where s0.master_id = #{masterId} and s0.name_index = #{nameIndex}

select count(1) from gc_subject s
where s.type=#{type} and  s.state!=#{state} and s.sub_id in
(select asso.subject_id from gc_subject_association asso where asso.master_id=#{masterId}

	and asso.subject_id in

		#{subId}


)

select s.*,v.video_name as gcVideo_videoName,v.id as gcVideo_id,f.video_long as gcVideo_long,f.file_type as video_f_file_type, coalesce(max(answer.update_time)) as lastActivityTime,s0.name as sub0Name,s0.Id as sub0Id from gc_subject s left join gc_subject s0 on s0.id = s.fid left join gc_video v on v.sub_id=s.id left join sys_file f on v.file_id=f.id left join gc_event e on e.video_id=v.id left join gc_user_answer answer on answer.event_id = e.id
left join gc_subject_association ass on s.fid=ass.subject_id and ass.master_id = #{masterId}
where s.fid in
#{subId}
group by s.id, v.id, f.id, s0.Id
order by max(answer.update_time) ${order}
order by s.order asc,s.create_time asc,s.id
order by s.order desc

select s.*,v.video_name as gcVideo_videoName,v.id as gcVideo_id,f.video_long as gcVideo_long,f.file_type as video_f_file_type, coalesce(max(answer.update_time))as lastActivityTime,s0.name as sub0Name,s0.Id as sub0Id from gc_subject s left join gc_subject s0 on s0.id = s.fid left join gc_video v on v.sub_id=s.id left join sys_file f on v.file_id=f.id left join gc_event e on e.video_id=v.id left join gc_user_answer answer on answer.event_id = e.id
left join gc_subject_association ass on s.fid=ass.subject_id and ass.master_id = #{masterId}
where s.fid in
#{subId}
group by s.id, v.id, f.video_long, f.file_type, s0.name, s0.Id
order by max(answer.update_time) ${order}
/*order by s.order asc,s.create_time desc,s.id*/ order by s.order asc,s.create_time asc,s.id
order by s.order asc

select s.*,v.video_name as gcVideo_videoName,v.id as gcVideo_id,f.video_long as gcVideo_long, v.video_source as video_source, f.file_type as video_f_file_type, f.id as video_f_id, f.file_url as video_file_url, f.file_type_index as video_f_file_index, f.name as video_f_name, f.save_type as video_f_save_type,s0.name as sub0Name,s0.Id as sub0Id, f.thumb_nail_url as thumb_nail_url from gc_subject s left join gc_subject s0 on s0.id = s.fid left join gc_video v on v.sub_id=s.id left join sys_file f on v.file_id=f.id left join gc_event e on e.video_id=v.id left join gc_user_answer answer on answer.event_id = e.id
left join gc_subject_association ass on s.fid=ass.subject_id and ass.master_id = #{masterId}
where s.fid in
#{subId}
and concat(v.video_name,v.video_name_index) like concat('%',#{context},'%')
order by max(answer.update_time) ${order}
order by coalesce(ass.ORDER,s.order) asc,s.id asc
order by s.order desc

SELECT gc.*, string_agg(tags.tag_text, ',') as course_tags
FROM gc_subject gc
		 LEFT JOIN gc_subject_tags tags ON tags.subject_id = gc.id AND tags.master_id = #{masterId}
WHERE gc.id = #{id}
GROUP BY gc.id
LIMIT 1

select tags.id as id,s.name,s.description,s.order, case when coalesce(tagass.close_subject,tags.close_subject)::jsonb @> to_jsonb(s.id::integer) then 0 else 1 end as subjectShowFlag, case tags.master_id when #{masterId} then 0 else 1 end as tagType, case tagass.master_id when #{masterId} then tagass.subject_order else tags.subject_order end as subject_order, s.id as id2 from gc_subject s LEFT JOIN GC_USER_ACCESS_PERMISSION uap ON UAP.SUB_PERMISSION::jsonb @> to_jsonb(s.id::integer) LEFT JOIN GC_USER_ACCESS UA ON UA.ID = UAP.USER_ACCESS_ID LEFT JOIN gc_subject_association sa ON ( S.id = sa.subject_id OR s.fid = sa.subject_id )AND ua.master_id = sa.master_id left join gc_subject_tags tags on tags.subject_id = s.id and( (sa.subject_id = tags.subject_id and tags.type = 1 and s.master_id = tags.master_id) or(tags.master_id = #{masterId})) left join gc_subject_tag_association tagass on tagass.tag_id = tags.id and tagass.master_id = #{masterId}
where s.id in
#{subId}
and tags.tag_text = #{tag}
group by s.id order by s.order

select s.*,p.id as subjectAssociationId from gc_subject s LEFT JOIN gc_user_access_permission p ON p.sub_permission::jsonb @> to_jsonb(s.id::integer) where p.id in
#{permissionIds}
and s.id is not null

select s2.*, ap.id as subjectAssociationId from GC_SUBJECT s left join gc_user_access_permission ap on ap.sub_permission::jsonb @> to_jsonb(s.id::integer) left join gc_subject s2 on s2.fid = s.id where ap.id in
#{permissionIds}
and s2.id is not null

select s.* from GC_SUBJECT s
					left join gc_master m on m.id = s.master_id
where m.context = #{portalId}
  and name_index = #{nameIndex}
	limit 1

select s2.*,u.id as userId,s.name as sub0Name from gc_access ac left join gc_user_access uac on uac.access_id = ac.id left join gc_user_access_permission p on p.user_access_id = uac.id left join gc_user u on u.id = uac.user_id left join gc_user_info info on info.id = u.info_id left join gc_subject s on p.sub_permission::jsonb @> to_jsonb(s.id::integer) left join gc_subject s2 on s2.fid = s.id where ac.id in
#{accessIds}
and u.id is not null
and s.id in
#{ids}
and s2.id in
#{ids}
order by concat(info.first_name,info.last_name) ${param.order}
order by concat(info.first_name,info.last_name) desc
limit #{param.limit}

select s2.num as subjectsSize, vnum.videoNum, info.avatar_file_id AS avatarFileId, info.first_name AS u_first_name, info.last_name AS u_last_name, f.id AS u_f_id, f."name" AS u_f_name, f.file_url AS u_f_file_url, f.save_type AS u_f_save_type, b.* from ( select count(1) as nums,a.* from (SELECT u.id as user_id ,u.info_id as info_id,p.video_id,s.* FROM gc_subject s LEFT JOIN gc_user_access_permission uap ON uap.sub_permission::jsonb @> to_jsonb(s.id::integer) LEFT JOIN gc_user_access ua ON UA.ID = UAP.USER_ACCESS_ID left join gc_user u on u.id = ua.user_id left join gc_subject s2 on s2.fid = s.id left join gc_video v on v.sub_id = s2.id left join gc_user_video_play p on p.video_id = v.id and p.user_id = u.id where 1=1 and p.play_state = 1 and ua.master_id = #{param.masterId} and p.play_state is not null and u.id in
#{userIds}
and s.id in
#{accessSubIds}
GROUP BY p.video_id, p.user_id ) as a GROUP BY a.id,a.user_id ) b left join (select count(v.id) as videoNum,s.id as id from gc_subject s left join gc_subject s2 on s2.fid = s.id left join gc_video v on v.sub_id = s2.id GROUP BY s.id ) vNum on vNum.videoNum = b.nums and b.id = vNum.id LEFT JOIN gc_user_info info ON info.id = b.info_id LEFT JOIN sys_file f ON f.id = info.avatar_file_id left join ( select count(*)as num,fid from gc_subject where "level" = 1 GROUP BY fid ) s2 on s2.fid = b.id left join ( select * from ( select sum(case when answer_json is null then 0 else 1 end) as anNums, sum(case when event_nums.event_id is null then 0 else 1 end) as eventNums, event_nums.* from (select an.answer_json, u.id as user_id,e.id as event_id,s.id as subject_id from gc_subject s left join gc_subject s2 on s.id = s2.fid left join gc_video v on v.sub_id = s2.id left join gc_event e on e.video_id = v.id left join gc_user u on u.id in
#{userIds}
left join gc_user_event ue on ue.event_id = e.id and ue.user_id = u.id and ue.master_id = #{param.masterId} left join gc_user_answer an on an.event_id = e.id and an.user_id = u.id and an.master_id = #{param.masterId} where s.id in
#{accessSubIds}
and ((e.upload_type = 2 and ue.id is not null ) or(e.upload_type = 1 ) or (e.upload_type is null and e.id is null) ) ) event_nums GROUP BY event_nums.user_id,subject_id ) comEvents where annums = eventNums ) eu on eu.user_id = b.user_id and b.id = eu.subject_id
where vNum.videoNum is not null and eu.anNums is not null
and b.id in
#{ids}
order by concat(info.first_name,info.last_name) ${param.order}
order by concat(info.first_name,info.last_name) desc

select count(1) from gc_subject
where "level" = 0
  and "state" = #{state}
  and create_user = #{userId}
  and master_id = #{masterId}

select a.fid from (SELECT count(v.id) as vnums , s.fid FROM gc_subject s LEFT JOIN gc_subject s0 ON s0.id = s.fid LEFT JOIN gc_video v ON v.sub_id = s.id WHERE s.fid IN
#{ids}
GROUP BY s.fid ) as a where a.vnums >0

SELECT DISTINCT ON (s.id)


FROM gc_subject s
left join gc_content_group_course_assignment cgc on cgc.course_id = s.id
left join gc_access ac ON cgc.content_group_id = ac.id
left join gc_user_access ua on ac.id = ua.access_id and ac.master_id = ua.master_id
left join sys_file f on s.sub_img_id=f.id
where s."level" = 0
and ua.user_id = #{userId}
and s.master_id = #{masterId}
and ua.master_id = #{masterId}


	and s.id not in

		#{ids}



	and s."name" like concat('%',#{name},'%')

group by s.id

	order by s.id ${orderType}, s.create_time ${orderType}

SELECT


FROM gc_subject s
left join sys_file f on s.sub_img_id=f.id
WHERE s."level" = 0


	and s.id not in

		#{ids}



	and s."name" like concat('%',#{name},'%')


	and s.create_user = #{userId}

and s.master_id = #{masterId}

	order by s.create_time ${orderType}

select DISTINCT ON (k.id,k.userId) * from ( select s.id,u.id as userId,s.name as sub0Name, coalesce( eu.anNums, 0 ) AS answeredNums, coalesce( eu.eventNums, 0 ) AS answeredSumNums , count(v.id) as subVideoNum , coalesce(plays.playNum,0) as playNum from gc_subject s LEFT JOIN gc_subject s2 ON s.id = s2.fid LEFT JOIN gc_video v ON v.sub_id = s2.id LEFT JOIN GC_USER u ON u.ID in
#{ids}
left join (SELECT COUNT(CASE WHEN b.play_state = 1 THEN 1 END) as playNum,b.user_id,b.video_id,b.sub_id from ( SELECT max( uvp.play_state )AS play_state, uvp.id, uvp.video_id, uvp.master_id, uvp.user_id,v.sub_id FROM gc_user_video_play uvp left join gc_video v on v.id = uvp.video_id where uvp.user_id in
#{ids}
and uvp.master_id = #{param.masterId} GROUP BY uvp.user_id, uvp.video_id, uvp.master_id, uvp.id, v.sub_id ) as b GROUP BY b.user_id,b.sub_id, b.video_id) plays on plays.sub_id = s2.id and plays.user_id = u.id LEFT JOIN gc_user_info info ON info.id = u.info_id LEFT JOIN sys_file f ON f.id = info.avatar_file_id LEFT JOIN (SELECT * FROM (SELECT sum( case when answer_json is null then 0 else 1 end) AS anNums, sum( case when event_nums.event_id is null then 0 else 1 end) AS eventNums, event_nums.answer_json::jsonb AS answer_json, event_nums.user_id, event_nums.subject_id2 FROM ( SELECT an.answer_json,u.id AS user_id,e.id AS event_id,s.id AS subject_id,s2.id AS subject_id2 FROM gc_subject s LEFT JOIN gc_subject s2 ON s.id = s2.fid LEFT JOIN gc_video v ON v.sub_id = s2.id LEFT JOIN gc_event e ON e.video_id = v.id LEFT JOIN gc_user u ON u.id IN
#{ids}
LEFT JOIN gc_user_event ue ON ue.event_id = e.id AND ue.user_id = u.id LEFT JOIN gc_user_answer an ON an.event_id = e.id AND an.user_id = u.id WHERE 1=1 AND ((( e.upload_type = 2 AND ue.id IS NOT NULL ) OR ( e.upload_type = 1 )) OR ( e.upload_type IS NULL AND e.id IS NULL ) ) ) event_nums GROUP BY event_nums.user_id, subject_id2, event_nums.answer_json::jsonb) comEvents ) eu ON eu.user_id = u.id AND eu.subject_id2 = s.id where 1=1 and s.id in
#{ids}
and u.id in
#{ids}
group by s2.id,u.id,s.id,eu.anNums,eu.eventNums,plays.playNum) as k where (k.answeredNums !=0 or k.playNum !=0) and (k.subVideoNum != 0 and k.answeredSumNums !=0)

select sub.id from gc_subject sub where id not in (
	select s.id from gc_user_access ua
						 left join gc_user_access_permission uap  on ua.id = uap.user_access_id
						 left join gc_subject s on uap.must_subject_json::jsonb @> to_jsonb(s.id::integer)
	where 1=1
	  and s.master_id = #{masterId}
	  and s.create_user = #{createUser}
	  and ua.master_id = #{masterId}
	group by s.id
)
and sub.master_id = #{masterId}
and sub.create_user = #{createUser}

select count(1) from gc_subject where
master_id = #{masterId}
and name_index = #{nameIndex}

select s.id from gc_subject s
where s.create_user = #{userId}
and s.master_id = #{masterId}
and s.state = 1
and s.level = 0
